export function selectedSkillNames(containerConfig: import('./container-config.js').ContainerConfig): string[] {
  const requested =
    containerConfig.skills === 'all'
      ? (() => {
          const sharedSkillsDir = path.join(process.cwd(), 'container', 'skills');
