            ? fs
                .readdirSync(sharedSkillsDir)
                .filter((entry) => {
                  try {
                    return fs.statSync(path.join(sharedSkillsDir, entry)).isDirectory();
                  } catch {
                    return false;
                  }
                })
                .sort()
            : [];
        })()
      : containerConfig.skills;

  return [...new Set([...requested, 'graphify'])];
}

